    def __init__(self):
        self.board = [" "] * 9
        self.current = "X"
        self.winner = None
        self.moves = []

    def available(self):
        return [i for i, c in enumerate(self.board) if c == " "]

    def play(self, pos):
        """Place the current player's mark at pos (0-8). Returns True on success."""
